# Generated by the MCRI team.
#
# Variant observation counts, stage 5: global per-assay counts.
#
# WES/WGS come from `sample_type`, already on `project_gt_stats`. Long-read is derived
# from project membership via `seqrdb_project_assay_dict`, so this needs no LRS
# `sample_type` anywhere -- no Django model change, no pipeline change, and none of the
# two-sample-type assumptions in the search layer have to move.
#
# A project with no assay row defaults to '' (short read) and is counted by sample_type
# exactly as before, so existing counts are unchanged for every existing project.
#
# NOTE: WES/WGS now additionally require `assay = ''`, so a long-read project's samples
# stop contributing to ac_wgs and contribute to ac_lrs instead. That is the intended
# behaviour, but it does change ac_wgs for any project marked as LRS.
import os
from string import Template

import clickhouse_backend.models
from django.db import migrations

from settings import DATABASES

CLICKHOUSE_WRITER_PASSWORD = os.environ.get('CLICKHOUSE_WRITER_PASSWORD', 'clickhouse_test')
CLICKHOUSE_WRITER_USER = os.environ.get('CLICKHOUSE_WRITER_USER', 'clickhouse')
CLICKHOUSE_DATABASE = DATABASES.get('clickhouse_write', {}).get('NAME', 'seqr')
SEQR_DATABASE = DATABASES['default']['NAME']
UINT16_MAX = 65535

CLICKHOUSE_AC_EXCLUDED_PROJECT_GUIDS = os.environ.get(
    'CLICKHOUSE_AC_EXCLUDED_PROJECT_GUIDS', '',
).split(',')

PROJECT_ASSAY_DICT = Template("""
CREATE DICTIONARY `seqrdb_project_assay_dict`
(
    `project_guid` String,
    `assay` String
)
PRIMARY KEY project_guid
SOURCE(POSTGRESQL(
    NAME 'seqr_postgres_named_collection'
    DATABASE $database
    QUERY 'select project_guid, assay from mcri_project_assay_lookup'
))
LIFETIME(MIN 0 MAX 0)
LAYOUT(COMPLEX_KEY_HASHED());
""").substitute(database=SEQR_DATABASE)

DROP_PROJECT_ASSAY_DICT = 'DROP DICTIONARY IF EXISTS `seqrdb_project_assay_dict`'

# Column order must match the target table exactly: a materialized view with TO inserts
# its SELECT columns positionally.
PROJECT_GT_STATS_TO_GT_STATS = Template(Template("""
CREATE MATERIALIZED VIEW `$reference_genome/$dataset_type/project_gt_stats_to_gt_stats_mv`
REFRESH EVERY 10 YEAR
TO `$reference_genome/$dataset_type/gt_stats`
AS SELECT
    key,
    $columns
FROM (
    SELECT *,
        (het_samples * 1) + (hom_samples * 2) AS ac,
        dictGetOrDefault('seqrdb_project_assay_dict', 'assay', project_guid, '') AS assay
    FROM `$reference_genome/$dataset_type/project_gt_stats`
    WHERE project_guid NOT IN $clickhouse_ac_excluded_project_guids
)
GROUP BY key
""").safe_substitute(
    clickhouse_ac_excluded_project_guids=CLICKHOUSE_AC_EXCLUDED_PROJECT_GUIDS,
))

LEGACY_PROJECT_GT_STATS_TO_GT_STATS = Template(Template("""
CREATE MATERIALIZED VIEW `$reference_genome/$dataset_type/project_gt_stats_to_gt_stats_mv`
REFRESH EVERY 10 YEAR
TO `$reference_genome/$dataset_type/gt_stats`
AS SELECT
    key,
    $columns
FROM `$reference_genome/$dataset_type/project_gt_stats`
WHERE project_guid NOT IN $clickhouse_ac_excluded_project_guids
GROUP BY key
""").safe_substitute(
    clickhouse_ac_excluded_project_guids=CLICKHOUSE_AC_EXCLUDED_PROJECT_GUIDS,
))

SNV_INDEL_COLUMNS = [
    "sumIf(ac, sample_type = 'WES' AND assay = '') ac_wes",
    "sumIf(ac, sample_type = 'WGS' AND assay = '') ac_wgs",
    "sumIf(ac, assay = 'LRS') ac_lrs",
    "sumIf(ac, affected = 'A') ac_affected",
    "sumIf(hom_samples, sample_type = 'WES' AND assay = '') hom_wes",
    "sumIf(hom_samples, sample_type = 'WGS' AND assay = '') hom_wgs",
    "sumIf(hom_samples, assay = 'LRS') hom_lrs",
    "sumIf(hom_samples, affected = 'A') hom_affected",
]
LEGACY_SNV_INDEL_COLUMNS = [
    "sumIf((het_samples * 1) + (hom_samples * 2), sample_type = 'WES') ac_wes",
    "sumIf((het_samples * 1) + (hom_samples * 2), sample_type = 'WGS') ac_wgs",
    "sumIf((het_samples * 1) + (hom_samples * 2), affected = 'A') ac_affected",
    "sumIf(hom_samples, sample_type = 'WES') hom_wes",
    "sumIf(hom_samples, sample_type = 'WGS') hom_wgs",
    "sumIf(hom_samples, affected = 'A') hom_affected",
]

GT_STATS_DICT_COLUMNS = ['ac_wes', 'ac_wgs', 'ac_lrs', 'ac_affected', 'hom_wes', 'hom_wgs', 'hom_lrs', 'hom_affected']
LEGACY_GT_STATS_DICT_COLUMNS = ['ac_wes', 'ac_wgs', 'ac_affected', 'hom_wes', 'hom_wgs', 'hom_affected']

GT_STATS_DICT = Template(Template("""
CREATE DICTIONARY `$reference_genome/$dataset_type/gt_stats_dict`
(
    key UInt32,
    $columns
)
PRIMARY KEY key
SOURCE(CLICKHOUSE(USER '$clickhouse_writer_user' PASSWORD '$clickhouse_writer_password' QUERY '$query'))
LIFETIME(MIN 0 MAX 0)
LAYOUT(FLAT(MAX_ARRAY_SIZE $size))
""").safe_substitute(
    clickhouse_writer_user=CLICKHOUSE_WRITER_USER,
    clickhouse_writer_password=CLICKHOUSE_WRITER_PASSWORD,
))

SNV_INDEL_TARGETS = [('GRCh37', 'SNV_INDEL', int(2e8)), ('GRCh38', 'SNV_INDEL', int(1e9))]


def _dict_sql(reference_genome, dataset_type, size, columns):
    projected = ', '.join(f'least({c}, {UINT16_MAX}) AS {c}' for c in columns)
    query = (
        f'SELECT key, {projected} '
        f'FROM {CLICKHOUSE_DATABASE}.`{reference_genome}/{dataset_type}/gt_stats`'
    )
    return GT_STATS_DICT.substitute(
        reference_genome=reference_genome,
        dataset_type=dataset_type,
        columns=',\n    '.join(f'{c} UInt16' for c in columns),
        query=query,
        size=size,
    )


def _operations():
    operations = []
    for reference_genome, dataset_type, size in SNV_INDEL_TARGETS:
        prefix = f'{reference_genome}/{dataset_type}'
        model = 'gtstatsgrch37snvindel' if reference_genome == 'GRCh37' else 'gtstatssnvindel'
        for col, after in (('ac_lrs', 'ac_wgs'), ('hom_lrs', 'hom_wgs')):
            operations.append(migrations.RunSQL(
                f'ALTER TABLE `{prefix}/gt_stats` ADD COLUMN `{col}` UInt32 DEFAULT 0 AFTER `{after}`;',
                f'ALTER TABLE `{prefix}/gt_stats` DROP COLUMN IF EXISTS `{col}`;',
                hints={'clickhouse': True},
                state_operations=[migrations.AddField(
                    model_name=model, name=col, field=clickhouse_backend.models.UInt32Field(),
                )],
            ))
        drop_mv = f'DROP TABLE IF EXISTS `{prefix}/project_gt_stats_to_gt_stats_mv`'
        operations.append(migrations.RunSQL(drop_mv, drop_mv, hints={'clickhouse': True}))
        operations.append(migrations.RunSQL(
            PROJECT_GT_STATS_TO_GT_STATS.substitute(
                reference_genome=reference_genome, dataset_type=dataset_type,
                columns=',\n    '.join(SNV_INDEL_COLUMNS),
            ),
            LEGACY_PROJECT_GT_STATS_TO_GT_STATS.substitute(
                reference_genome=reference_genome, dataset_type=dataset_type,
                columns=',\n    '.join(LEGACY_SNV_INDEL_COLUMNS),
            ),
            hints={'clickhouse': True},
        ))
        drop_dict = f'DROP DICTIONARY IF EXISTS `{prefix}/gt_stats_dict`'
        operations.append(migrations.RunSQL(drop_dict, drop_dict, hints={'clickhouse': True}))
        operations.append(migrations.RunSQL(
            _dict_sql(reference_genome, dataset_type, size, GT_STATS_DICT_COLUMNS),
            _dict_sql(reference_genome, dataset_type, size, LEGACY_GT_STATS_DICT_COLUMNS),
            hints={'clickhouse': True},
        ))
    return operations


class Migration(migrations.Migration):

    dependencies = [
        ('clickhouse_search', '0025_narrow_gt_stats_dict'),
    ]

    operations = [
        migrations.RunSQL(PROJECT_ASSAY_DICT, DROP_PROJECT_ASSAY_DICT, hints={'clickhouse': True}),
        *_operations(),
    ]
